// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public { c = new Reentrance(); }

    // fuzz params: depositor private key (uint256) to derive an address, and an amount to deposit
    function testFuzz_property(uint256 depositorKey, uint256 amount) public {
        // keep depositorKey a valid ECDSA private key
        // the Secp256k1 curve order is ~1.1579e77; require key < order
        // keep amount in a reasonable range so vm.deal and value transfers work
        uint256 curveOrder = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141;
        vm.assume(depositorKey > 0 && depositorKey < curveOrder);
        amount = bound(amount, 1, 1 ether);

        address depositor = vm.addr(uint256(depositorKey));

        // Deploy a recording helper which will act as the depositor (msg.sender) when withdrawing.
        // The helper records the last received msg.value when receive()/fallback() is invoked.
        Recorder recorder = new Recorder();

        // Fund the depositor EOA so it can call payable addToBalance
        vm.deal(depositor, amount);

        // Make the depositor call addToBalance() to store `amount` in c.userBalance[depositor].
        vm.prank(depositor);
        c.addToBalance{value: amount}();

        // Now, we want the deposit to be withdrawn to a contract address (recorder) that will record the received value.
        // To cause c.withdrawBalance() to attempt to send to msg.sender == recorder, we must have recorder be msg.sender in that call.
        // So we fund the recorder (not strictly necessary) and then invoke withdrawBalance() as if called by the recorder.
        // But the stored balance is indexed by the original depositor address. To make recorder the msg.sender while still targeting the depositor's stored balance,
        // we exploit that c uses msg.sender to index balances. Therefore, to observe the difference, we must have the same address be both the depositor (that stored the balance) and the caller that withdraws.
        // The EOA depositor cannot be a contract. To satisfy the adversarial/observing requirement, we instead make the depositor be the recorder contract itself: derive a private key, but the recorder must be the caller that holds the balance.
        // To reconcile this, we performed the deposit from the EOA 'depositor'. Now we want the recorder to be the caller that receives funds. The only way to make the recipient record msg.value is to have the recorder be msg.sender when withdrawBalance() is called.
        // Therefore, we re-run the scenario with the recorder as the depositor: ensure recorder has a stored balance by making it call addToBalance. We'll transfer Ether to recorder and have it call addToBalance.

        // Reset: create a fresh instance and repeat with recorder as depositor to keep the scenario simple and admissible.
        c = new Reentrance();
        // fund the recorder so it can deposit
        vm.deal(address(recorder), amount);
        vm.prank(address(recorder));
        c.addToBalance{value: amount}();

        // Clear any previous recording and then call withdrawBalance() as recorder so msg.sender == recorder
        recorder.clear();
        vm.prank(address(recorder));
        bool ok;
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: for any depositor (here recorder) with positive stored balance, the reference will attempt to forward that stored balance; thus when the call succeeds, the recorder will observe msg.value == amount.
        // The mutant that forwards zero breaks this: recorder would observe msg.value == 0 for that input. We assert that if withdrawBalance completed (did not revert), then recorder.lastReceived() == amount.
        // This property holds for the reference for all admissible inputs; the mutant (which forwards 0) will make the assertion fail for some inputs (when the call returns success).
        if (ok) {
            // If the call succeeded, the recorder must have recorded receiving the forwarded value equal to amount.
            assertTrue(recorder.lastReceived() == amount);
        } else {
            // If the call reverted, the reference would revert only if the external call failed; the mutant may still revert or not depending on behavior.
            // We accept either outcome here; the distinguishing case is where withdrawBalance succeeds but forwarded value differs.
            assertTrue(true);
        }
    }
}

// Recording helper: records last received msg.value and exposes it via a getter.
contract Recorder {
    uint256 public last;
    event Received(address from, uint256 value);

    receive() external payable {
        last = msg.value;
        emit Received(msg.sender, msg.value);
    }

    fallback() external payable {
        last = msg.value;
        emit Received(msg.sender, msg.value);
    }

    function lastReceived() external view returns (uint256) {
        return last;
    }

    function clear() external {
        last = 0;
    }
}
